#!/bin/sh
# Generated by reflex generate. Edit the CLI resource source, then regenerate.
set -eu

fail() { printf '%s\n' "Linux package: $*" >&2; exit 1; }

[ "$#" -eq 5 ] || fail "expected stage or package, launcher, icon folder, executable, and package ID"
mode=$1
desktop=$2
icons=$3
executable=$4
package=$5
case "$mode" in
    stage) ;; # CMake prepares assets before linking.
    package) [ -f "$executable" ] || fail "missing executable: $executable" ;;
    *) fail "unknown operation: $mode" ;;
esac
[ -f "$desktop" ] || fail "missing launcher: $desktop; regenerate the project"
output=$(dirname -- "$executable")
[ -f "$desktop.package-deb.sh" ] || fail "missing Debian packaging script; regenerate the project"
root="$output/package/usr"
mkdir -p "$root/bin" "$root/share/applications"
install -m 755 "$desktop.package-deb.sh" "$output/package-deb.sh"
install -m 644 "$desktop" "$root/share/applications/$package.desktop"
# Refresh the binary on incremental builds too. The first CMake build copies it after linking.
if [ -f "$executable" ]; then
    install -m 755 "$executable" "$root/bin/$(basename -- "$executable")"
fi
# This subtree is generated exclusively from the configured icon sizes.
rm -rf -- "$root/share/icons/hicolor"
found=false
for size in "$icons"/*x*; do
    [ -d "$size/apps" ] || continue
    set -- "$size/apps/"*.png
    [ "$#" -eq 1 ] && [ -f "$1" ] || fail "expected one PNG in $size/apps/"
    destination="$root/share/icons/hicolor/$(basename -- "$size")/apps"
    mkdir -p "$destination"
    install -m 644 "$1" "$destination/$package.png"
    found=true
done
[ "$found" = true ] || fail "no PNG icon sizes found in $icons"
